'use strict';

const { spawn } = require('node:child_process');
const { EventEmitter } = require('node:events');
const {
  getKeyCode,
  getModifierMask,
  isModifierKey
} = require('./keycodes');

const DEFAULT_OPTIONS = {
  portPath: '',
  baudRate: 115200,
  probeTimeoutMs: 1200,
  commandTimeoutMs: 800,
  tolerancePx: 2,
  maxStepPx: 18,
  minStepPx: 1,
  adaptiveMove: true,
  targetStepPx: 20,
  minTargetStepPx: 2,
  slowRadiusPx: 90,
  logicalPxPerHidCount: 1,
  adaptiveSmoothing: 0.35,
  stepDelayMs: 14,
  clickHoldMs: 70,
  clickPreDelayMs: 20,
  clickPostDelayMs: 30,
  clickIntervalMs: 80,
  keyHoldMs: 50,
  moveTimeoutMs: 5000,
  stallThreshold: 18,
  cursorTimeoutMs: 2000,
  platform: process.platform,
  swiftPath: '/usr/bin/swift',
  logger: console
};

const MAC_CURSOR_HELPER_SOURCE = `
import CoreGraphics
import Foundation

while let line = readLine() {
  let command = line.trimmingCharacters(in: .whitespacesAndNewlines)
  if command == "POS" {
    if let event = CGEvent(source: nil) {
      let point = event.location
      print("\\(point.x) \\(point.y)")
      fflush(stdout)
    } else {
      print("ERR no-event")
      fflush(stdout)
    }
  } else if command == "EXIT" {
    exit(0)
  } else {
    print("ERR unknown-command")
    fflush(stdout)
  }
}
`;

const ATOMS3U_TEXT_PATTERNS = [
  /atoms3u/i,
  /m5stack/i,
  /tinyusb/i,
  /esp32/i,
  /espressif/i,
  /usbmodem/i,
  /modem/i,
  /cdc/i
];

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

function callLogger(logger, level, ...args) {
  const fn = logger && typeof logger[level] === 'function' ? logger[level] : null;
  if (fn) {
    fn(...args);
  }
}

function getSerialPortClass(options = {}) {
  if (options.SerialPort) {
    return options.SerialPort;
  }
  if (options.serialPortClass) {
    return options.serialPortClass;
  }

  try {
    return require('serialport').SerialPort;
  } catch (error) {
    throw new Error(`serialport dependency is required for AtomS3U input: ${error.message}`);
  }
}

function normalizeButton(button) {
  const normalized = String(button || 'left').trim().toLowerCase();
  if (normalized === 'right' || normalized === 'middle' || normalized === 'left') {
    return normalized;
  }
  throw new Error(`Unsupported AtomS3U mouse button: ${button}`);
}

function normalizePlatform(platform) {
  return platform === 'darwin' ? 'darwin' : 'win32';
}

function normalizeKeyTapArgs(modifiersOrOptions = [], maybeOptions = {}) {
  if (
    modifiersOrOptions &&
    typeof modifiersOrOptions === 'object' &&
    !Array.isArray(modifiersOrOptions)
  ) {
    return {
      modifiers: Array.isArray(modifiersOrOptions.modifiers) ? modifiersOrOptions.modifiers : [],
      options: modifiersOrOptions
    };
  }

  return {
    modifiers: Array.isArray(modifiersOrOptions) ? modifiersOrOptions : [],
    options: maybeOptions && typeof maybeOptions === 'object' ? maybeOptions : {}
  };
}

function normalizePoint(point) {
  if (
    !point ||
    !Number.isFinite(point.x) ||
    !Number.isFinite(point.y)
  ) {
    throw new Error('getCursorPos must return { x, y } with finite numbers');
  }

  return {
    x: Number(point.x),
    y: Number(point.y)
  };
}

function normalizeTarget(value, label) {
  const number = Number(value);
  if (!Number.isFinite(number)) {
    throw new Error(`${label} must be a finite number`);
  }
  return number;
}

function createMacCursorPositionProvider(options = {}) {
  const swiftPath = options.swiftPath || DEFAULT_OPTIONS.swiftPath;
  let helper = null;
  let buffer = '';
  let closed = false;
  const pending = [];

  function rejectAll(error) {
    while (pending.length > 0) {
      const waiter = pending.shift();
      clearTimeout(waiter.timer);
      waiter.reject(error);
    }
  }

  function handleData(data) {
    buffer += data.toString('utf8');

    while (true) {
      const match = buffer.match(/\r?\n/);
      if (!match || typeof match.index !== 'number') {
        break;
      }

      const line = buffer.slice(0, match.index).trim();
      buffer = buffer.slice(match.index + match[0].length);
      const waiter = pending.shift();
      if (!waiter) {
        continue;
      }

      clearTimeout(waiter.timer);
      if (/^ERR\b/.test(line)) {
        waiter.reject(new Error(`macOS cursor helper failed: ${line}`));
        continue;
      }

      const [xText, yText] = line.split(/\s+/);
      const x = Number(xText);
      const y = Number(yText);
      if (!Number.isFinite(x) || !Number.isFinite(y)) {
        waiter.reject(new Error(`macOS cursor helper returned invalid position: ${line}`));
        continue;
      }

      waiter.resolve({ x, y });
    }
  }

  function ensureHelper() {
    if (closed) {
      throw new Error('macOS cursor helper is closed');
    }
    if (helper && !helper.killed) {
      return helper;
    }

    helper = spawn(swiftPath, ['-e', MAC_CURSOR_HELPER_SOURCE], {
      stdio: ['pipe', 'pipe', 'pipe']
    });

    helper.stdout.on('data', handleData);
    helper.stderr.on('data', (data) => {
      callLogger(options.logger, 'warn', '[AtomS3U cursor helper]', data.toString('utf8').trim());
    });
    helper.on('error', (error) => {
      rejectAll(new Error(`Failed to start macOS cursor helper: ${error.message}`));
    });
    helper.on('close', (code, signal) => {
      const reason = signal ? `signal ${signal}` : `code ${code}`;
      helper = null;
      rejectAll(new Error(`macOS cursor helper exited with ${reason}`));
    });

    return helper;
  }

  function getCursorPos() {
    return new Promise((resolve, reject) => {
      let currentHelper;
      try {
        currentHelper = ensureHelper();
      } catch (error) {
        reject(error);
        return;
      }

      const waiter = {
        resolve,
        reject,
        timer: setTimeout(() => {
          const index = pending.indexOf(waiter);
          if (index >= 0) {
            pending.splice(index, 1);
          }
          reject(new Error('Timed out waiting for macOS cursor helper'));
        }, options.cursorTimeoutMs || DEFAULT_OPTIONS.cursorTimeoutMs)
      };

      pending.push(waiter);
      currentHelper.stdin.write('POS\n', (error) => {
        if (!error) {
          return;
        }
        const index = pending.indexOf(waiter);
        if (index >= 0) {
          pending.splice(index, 1);
        }
        clearTimeout(waiter.timer);
        reject(error);
      });
    });
  }

  function close() {
    closed = true;
    if (!helper) {
      rejectAll(new Error('macOS cursor helper closed'));
      return;
    }

    try {
      helper.stdin.write('EXIT\n');
    } catch (_) {
      // Ignore close-time helper failures.
    }
    helper.kill();
    helper = null;
    rejectAll(new Error('macOS cursor helper closed'));
  }

  return {
    getCursorPos,
    close
  };
}

function resolveCursorProvider(explicitProvider, options, state) {
  if (typeof explicitProvider === 'function') {
    return explicitProvider;
  }
  if (typeof options.getCursorPos === 'function') {
    return options.getCursorPos;
  }

  const platform = options.platform || process.platform;
  if (platform !== 'darwin') {
    throw new Error('AtomS3U moveTo requires getCursorPos on non-macOS platforms');
  }

  if (!state.macCursorProvider) {
    state.macCursorProvider = createMacCursorPositionProvider(options);
  }
  return state.macCursorProvider.getCursorPos;
}

function deviceSearchText(device) {
  return [
    device.path,
    device.manufacturer,
    device.serialNumber,
    device.vendorId,
    device.productId,
    device.friendlyName
  ]
    .filter(Boolean)
    .join(' ');
}

function looksLikeAtomS3UDevice(device) {
  return ATOMS3U_TEXT_PATTERNS.some((pattern) => pattern.test(deviceSearchText(device)));
}

function toDeviceInfo(port) {
  const path = preferCallableDarwinPort(port.path);
  return {
    path,
    portPath: path,
    listedPath: port.path,
    kind: 'atoms3u',
    manufacturer: port.manufacturer || '',
    serialNumber: port.serialNumber || '',
    vendorId: port.vendorId || '',
    productId: port.productId || '',
    friendlyName: port.friendlyName || port.path,
    isUsbLike:
      /usb/i.test(path || '') ||
      /usb/i.test(port.manufacturer || '') ||
      /usb/i.test(port.friendlyName || '') ||
      /modem/i.test(path || '')
  };
}

function preferCallableDarwinPort(path) {
  if (process.platform === 'darwin' && /^\/dev\/tty\./.test(path || '')) {
    return path.replace('/dev/tty.', '/dev/cu.');
  }
  return path;
}

function createLineReader(serialPortInstance) {
  let buffer = '';
  const pending = [];

  function cleanupWaiter(waiter) {
    serialPortInstance.off('data', waiter.onData);
    serialPortInstance.off('error', waiter.onError);
    clearTimeout(waiter.timer);
  }

  function checkWaiters() {
    for (let waiterIndex = 0; waiterIndex < pending.length; waiterIndex += 1) {
      const waiter = pending[waiterIndex];
      for (let lineIndex = 0; lineIndex < waiter.lines.length; lineIndex += 1) {
        const line = waiter.lines[lineIndex];
        if (waiter.predicate(line)) {
          pending.splice(waiterIndex, 1);
          cleanupWaiter(waiter);
          waiter.resolve(line);
          return true;
        }
      }
    }
    return false;
  }

  function pushData(data) {
    buffer += data.toString('utf8');

    while (true) {
      const match = buffer.match(/\r?\n/);
      if (!match || typeof match.index !== 'number') {
        break;
      }

      const line = buffer.slice(0, match.index).trim();
      buffer = buffer.slice(match.index + match[0].length);
      if (line.length === 0) {
        continue;
      }

      for (const waiter of pending) {
        waiter.lines.push(line);
      }
      checkWaiters();
    }
  }

  serialPortInstance.on('data', pushData);

  function waitForLine(predicate, timeoutMs) {
    return new Promise((resolve, reject) => {
      const waiter = {
        lines: [],
        predicate,
        resolve,
        reject,
        onData: () => {},
        onError: (error) => {
          const index = pending.indexOf(waiter);
          if (index >= 0) {
            pending.splice(index, 1);
          }
          cleanupWaiter(waiter);
          reject(error);
        },
        timer: null
      };

      waiter.timer = setTimeout(() => {
        const index = pending.indexOf(waiter);
        if (index >= 0) {
          pending.splice(index, 1);
        }
        cleanupWaiter(waiter);
        reject(new Error('Timed out waiting for AtomS3U response'));
      }, timeoutMs);

      serialPortInstance.on('error', waiter.onError);
      pending.push(waiter);
    });
  }

  function stop() {
    serialPortInstance.off('data', pushData);
    for (const waiter of [...pending]) {
      cleanupWaiter(waiter);
      waiter.reject(new Error('AtomS3U line reader stopped'));
    }
    pending.length = 0;
  }

  return {
    waitForLine,
    stop
  };
}

async function listDevices(options = {}) {
  const SerialPort = getSerialPortClass(options);
  const ports = await SerialPort.list();
  return ports.map(toDeviceInfo);
}

async function detectAtomS3UDevices(options = {}) {
  const devices = await listDevices(options);
  return devices.filter(looksLikeAtomS3UDevice);
}

async function withProbePort(portPath, options, fn) {
  const SerialPort = getSerialPortClass(options);
  const port = new SerialPort({
    path: portPath,
    baudRate: options.baudRate,
    autoOpen: false
  });
  const lineReader = createLineReader(port);

  try {
    await new Promise((resolve, reject) => {
      port.open((error) => {
        if (error) reject(error);
        else resolve();
      });
    });
    return await fn(port, lineReader);
  } finally {
    lineReader.stop();
    if (port.isOpen) {
      await new Promise((resolve) => port.close(() => resolve()));
    }
  }
}

async function writeLine(port, line) {
  await new Promise((resolve, reject) => {
    port.write(`${line}\n`, (error) => {
      if (error) {
        reject(error);
        return;
      }
      port.drain((drainError) => {
        if (drainError) reject(drainError);
        else resolve();
      });
    });
  });
}

async function probeAtomS3UDevice(portPath, userOptions = {}) {
  if (!portPath || typeof portPath !== 'string') {
    return {
      available: false,
      portPath: portPath || '',
      reason: 'AtomS3U portPath is required'
    };
  }

  const options = {
    ...DEFAULT_OPTIONS,
    ...userOptions,
    portPath,
    logger: Object.prototype.hasOwnProperty.call(userOptions, 'logger') ? userOptions.logger : null
  };
  const devices = await listDevices(options).catch(() => []);
  const device = devices.find((item) => item.path === portPath);

  try {
    await withProbePort(portPath, options, async (port, lineReader) => {
      const responsePromise = lineReader.waitForLine(
        (line) => line === 'OK PONG' || /^OK INFO /.test(line),
        options.probeTimeoutMs
      );
      await writeLine(port, 'PING');
      await responsePromise;
    });
    return {
      available: true,
      kind: 'atoms3u',
      portPath,
      baudRate: options.baudRate,
      device
    };
  } catch (error) {
    return {
      available: false,
      kind: 'atoms3u',
      portPath,
      baudRate: options.baudRate,
      device,
      reason: error?.message || String(error)
    };
  }
}

async function autoDetectAtomS3U(options = {}) {
  const candidates = await detectAtomS3UDevices(options);
  const probeCandidates = candidates.length > 0 ? candidates : await listDevices(options);
  const failedReasons = [];

  for (const candidate of probeCandidates) {
    const result = await probeAtomS3UDevice(candidate.path, options);
    if (result.available) {
      return {
        ...result,
        device: result.device || candidate,
        candidates: probeCandidates
      };
    }
    failedReasons.push(`${candidate.path}: ${result.reason || 'probe failed'}`);
  }

  return {
    available: false,
    kind: 'atoms3u',
    candidates: probeCandidates,
    reason: buildAutoDetectFailureReason(probeCandidates, failedReasons)
  };
}

function buildAutoDetectFailureReason(candidates, failedReasons) {
  const suffix = failedReasons.length > 0 ? ` (${failedReasons.join('; ')})` : '';
  const hasEspressifJtag = candidates.some((candidate) => (
    /espressif/i.test(candidate.manufacturer || '') &&
    /303a/i.test(candidate.vendorId || '') &&
    /1001/i.test(candidate.productId || '')
  ));

  if (hasEspressifJtag) {
    return `No available AtomS3U HID device found${suffix}. ` +
      'The board appears as Espressif USB-Serial/JTAG, so it is not running the TinyUSB HID firmware; reset it into the app firmware or re-upload the atoms3lite/atoms3u TinyUSB firmware.';
  }

  return failedReasons.length > 0
    ? `No available AtomS3U HID device found${suffix}`
    : 'No AtomS3U-like serial devices found';
}

function getPositiveNumber(value, fallback) {
  const number = Number(value);
  return Number.isFinite(number) && number > 0 ? number : fallback;
}

function buildLegacyRelativeStep(dx, dy, options) {
  const activeX = Math.abs(dx) > options.tolerancePx;
  const activeY = Math.abs(dy) > options.tolerancePx;

  if (!activeX && !activeY) {
    return { x: 0, y: 0 };
  }

  const distance = Math.sqrt(dx * dx + dy * dy);
  const maxStep = Number.isFinite(options.maxStepPx) && options.maxStepPx > 0
    ? options.maxStepPx
    : DEFAULT_OPTIONS.maxStepPx;
  const minStep = Number.isFinite(options.minStepPx) && options.minStepPx > 0
    ? options.minStepPx
    : DEFAULT_OPTIONS.minStepPx;
  const targetMagnitude = clamp(Math.ceil(distance / 10), minStep, maxStep);
  const scale = distance > 0 ? targetMagnitude / distance : 0;

  let stepX = activeX ? Math.round(dx * scale) : 0;
  let stepY = activeY ? Math.round(dy * scale) : 0;

  stepX = clamp(stepX, -maxStep, maxStep);
  stepY = clamp(stepY, -maxStep, maxStep);

  if (stepX === 0 && activeX) {
    stepX = dx > 0 ? 1 : -1;
  }
  if (stepY === 0 && activeY) {
    stepY = dy > 0 ? 1 : -1;
  }

  return { x: stepX, y: stepY };
}

function buildAdaptiveRelativeStep(dx, dy, options, movementState) {
  const activeX = Math.abs(dx) > options.tolerancePx;
  const activeY = Math.abs(dy) > options.tolerancePx;

  if (!activeX && !activeY) {
    return { x: 0, y: 0 };
  }

  const distance = Math.sqrt(dx * dx + dy * dy);
  const maxStep = getPositiveNumber(options.maxStepPx, DEFAULT_OPTIONS.maxStepPx);
  const minStep = getPositiveNumber(options.minStepPx, DEFAULT_OPTIONS.minStepPx);
  const targetStepPx = getPositiveNumber(options.targetStepPx, DEFAULT_OPTIONS.targetStepPx);
  const minTargetStepPx = getPositiveNumber(options.minTargetStepPx, DEFAULT_OPTIONS.minTargetStepPx);
  const slowRadiusPx = getPositiveNumber(options.slowRadiusPx, DEFAULT_OPTIONS.slowRadiusPx);
  const logicalPxPerHidCount = getPositiveNumber(
    movementState?.logicalPxPerHidCount,
    getPositiveNumber(options.logicalPxPerHidCount, DEFAULT_OPTIONS.logicalPxPerHidCount)
  );

  const easing = clamp(distance / slowRadiusPx, 0, 1);
  const desiredLogicalMagnitude = clamp(
    targetStepPx * easing,
    Math.min(minTargetStepPx, distance),
    Math.max(minTargetStepPx, Math.min(targetStepPx, distance))
  );
  const targetMagnitude = clamp(
    Math.ceil(desiredLogicalMagnitude / logicalPxPerHidCount),
    minStep,
    maxStep
  );
  const scale = distance > 0 ? targetMagnitude / distance : 0;

  let stepX = activeX ? Math.round(dx * scale) : 0;
  let stepY = activeY ? Math.round(dy * scale) : 0;

  stepX = clamp(stepX, -maxStep, maxStep);
  stepY = clamp(stepY, -maxStep, maxStep);

  if (stepX === 0 && activeX) {
    stepX = dx > 0 ? 1 : -1;
  }
  if (stepY === 0 && activeY) {
    stepY = dy > 0 ? 1 : -1;
  }

  return { x: stepX, y: stepY };
}

function buildRelativeStep(dx, dy, options, movementState) {
  if (options.adaptiveMove === false) {
    return buildLegacyRelativeStep(dx, dy, options);
  }
  return buildAdaptiveRelativeStep(dx, dy, options, movementState);
}

function updateLogicalMoveEstimate(movementState, previousPoint, point, previousStep, options) {
  if (!movementState || !previousPoint || !previousStep || options.adaptiveMove === false) {
    return;
  }

  const hidDistance = Math.sqrt(previousStep.x * previousStep.x + previousStep.y * previousStep.y);
  if (hidDistance < 1) {
    return;
  }

  const logicalDx = point.x - previousPoint.x;
  const logicalDy = point.y - previousPoint.y;
  const logicalDistance = Math.sqrt(logicalDx * logicalDx + logicalDy * logicalDy);
  if (!Number.isFinite(logicalDistance) || logicalDistance < 0.25) {
    return;
  }

  const observed = clamp(logicalDistance / hidDistance, 0.05, 8);
  const smoothing = clamp(Number(options.adaptiveSmoothing), 0.01, 1);
  movementState.logicalPxPerHidCount =
    movementState.logicalPxPerHidCount * (1 - smoothing) + observed * smoothing;
}

function emitMoveStep(options, event) {
  if (typeof options.onMoveStep !== 'function') {
    return;
  }

  try {
    options.onMoveStep(event);
  } catch (error) {
    callLogger(options.logger, 'warn', '[AtomS3U moveTo] onMoveStep failed:', error);
  }
}

function createAtomS3UInput(userOptions = {}) {
  const options = { ...DEFAULT_OPTIONS, ...userOptions };
  const logger = options.logger === null ? null : (options.logger || console);

  let port = null;
  let lineReader = null;
  let connected = false;
  let lastError = '';
  let currentPath = options.portPath || '';
  let commandQueue = Promise.resolve();
  let pressedModifierMask = 0;
  const pressedKeyCodes = new Set();
  const cursorProviderState = {
    macCursorProvider: null
  };

  function resetKeyState() {
    pressedModifierMask = 0;
    pressedKeyCodes.clear();
  }

  async function ensurePortPath() {
    if (currentPath) {
      return currentPath;
    }

    const detection = await autoDetectAtomS3U(options);
    if (!detection.available || !detection.portPath) {
      throw new Error(detection.reason || 'No AtomS3U HID device found');
    }

    currentPath = detection.portPath;
    return currentPath;
  }

  function bindPortEvents(serialPortInstance) {
    serialPortInstance.on('error', (error) => {
      connected = false;
      lastError = error?.message || String(error);
      callLogger(logger, 'error', '[AtomS3U] serial error:', error);
    });

    serialPortInstance.on('close', () => {
      connected = false;
      callLogger(logger, 'warn', '[AtomS3U] serial port closed');
    });
  }

  async function connect() {
    if (port && connected) {
      return;
    }

    const path = await ensurePortPath();
    const SerialPort = getSerialPortClass(options);
    const serialPortInstance = new SerialPort({
      path,
      baudRate: options.baudRate,
      autoOpen: false
    });

    bindPortEvents(serialPortInstance);
    lineReader = createLineReader(serialPortInstance);

    await new Promise((resolve, reject) => {
      serialPortInstance.open((error) => {
        if (error) reject(error);
        else resolve();
      });
    });

    port = serialPortInstance;
    connected = true;
    lastError = '';

    try {
      await sendCommand('PING', (line) => line === 'OK PONG', { rejectOnError: false });
    } catch (error) {
      lastError = error?.message || String(error);
      connected = false;
      port = null;
      if (lineReader) {
        lineReader.stop();
        lineReader = null;
      }
      await new Promise((resolve) => serialPortInstance.close(() => resolve()));
      throw error;
    }
  }

  async function disconnect() {
    if (port && connected) {
      try {
        await releaseKeys();
      } catch (error) {
        callLogger(logger, 'warn', '[AtomS3U] release keys before disconnect failed:', error);
        resetKeyState();
      }
    } else {
      resetKeyState();
    }

    if (cursorProviderState.macCursorProvider) {
      cursorProviderState.macCursorProvider.close();
      cursorProviderState.macCursorProvider = null;
    }

    if (!port) {
      connected = false;
      return;
    }

    const currentPort = port;
    const currentLineReader = lineReader;
    port = null;
    lineReader = null;
    connected = false;

    if (currentLineReader) {
      currentLineReader.stop();
    }

    await new Promise((resolve) => {
      currentPort.close(() => resolve());
    });
  }

  async function sendCommandNow(command, predicate, commandOptions = {}) {
    if (!port || !connected || !lineReader) {
      throw new Error('AtomS3U is not connected');
    }

    const rejectOnError = commandOptions.rejectOnError !== false;
    const responsePromise = lineReader.waitForLine((line) => {
      if (rejectOnError && /^ERR\b/.test(line)) {
        return true;
      }
      return predicate ? predicate(line) : /^OK\b/.test(line);
    }, options.commandTimeoutMs);

    await writeLine(port, command);
    const response = await responsePromise;
    if (/^ERR\b/.test(response)) {
      throw new Error(response);
    }
    return response;
  }

  function sendCommand(command, predicate, commandOptions) {
    const run = commandQueue
      .catch(() => {})
      .then(() => sendCommandNow(command, predicate, commandOptions));
    commandQueue = run.catch(() => {});
    return run;
  }

  async function getHealth() {
    return {
      connected,
      kind: 'atoms3u',
      portPath: currentPath || undefined,
      baudRate: options.baudRate,
      reason: connected ? undefined : lastError || 'AtomS3U not connected'
    };
  }

  async function sendRelativeMove(dx, dy) {
    await connect();

    const boundedX = clamp(Math.round(dx), -127, 127);
    const boundedY = clamp(Math.round(dy), -127, 127);

    if (boundedX === 0 && boundedY === 0) {
      return;
    }

    await sendCommand(`MOVE ${boundedX} ${boundedY}`, (line) => line === 'OK MOVE');
  }

  async function moveTo(targetX, targetY, getCursorPos) {
    const target = {
      x: normalizeTarget(targetX, 'targetX'),
      y: normalizeTarget(targetY, 'targetY')
    };
    const cursorProvider = resolveCursorProvider(getCursorPos, options, cursorProviderState);

    await connect();

    const startAt = Date.now();
    let previousDistance = Number.POSITIVE_INFINITY;
    let stallCount = 0;
    let iteration = 0;
    let previousPoint = null;
    let previousStep = null;
    const movementState = {
      logicalPxPerHidCount: getPositiveNumber(
        options.logicalPxPerHidCount,
        DEFAULT_OPTIONS.logicalPxPerHidCount
      )
    };

    while (Date.now() - startAt <= options.moveTimeoutMs) {
      const point = normalizePoint(await Promise.resolve(cursorProvider()));
      updateLogicalMoveEstimate(movementState, previousPoint, point, previousStep, options);

      const dx = target.x - point.x;
      const dy = target.y - point.y;

      if (Math.abs(dx) <= options.tolerancePx && Math.abs(dy) <= options.tolerancePx) {
        emitMoveStep(options, {
          device: 'atoms3u',
          phase: 'done',
          iteration,
          elapsedMs: Date.now() - startAt,
          target,
          point,
          delta: { dx, dy },
          logicalPxPerHidCount: movementState.logicalPxPerHidCount,
          tolerancePx: options.tolerancePx
        });
        return;
      }

      const distance = Math.sqrt(dx * dx + dy * dy);
      if (distance >= previousDistance - 0.25) {
        stallCount += 1;
      } else {
        stallCount = 0;
      }

      if (stallCount >= options.stallThreshold) {
        throw new Error('AtomS3U relative movement stalled before reaching target');
      }

      previousDistance = distance;

      const step = buildRelativeStep(dx, dy, options, movementState);
      emitMoveStep(options, {
        device: 'atoms3u',
        phase: 'step',
        iteration,
        elapsedMs: Date.now() - startAt,
        target,
        point,
        delta: { dx, dy },
        distance,
        step,
        stallCount,
        logicalPxPerHidCount: movementState.logicalPxPerHidCount,
        tolerancePx: options.tolerancePx,
        stepDelayMs: options.stepDelayMs
      });

      await sendRelativeMove(step.x, step.y);
      previousPoint = point;
      previousStep = step;
      await sleep(options.stepDelayMs);
      iteration += 1;
    }

    emitMoveStep(options, {
      device: 'atoms3u',
      phase: 'timeout',
      iteration,
      elapsedMs: Date.now() - startAt,
      target
    });
    throw new Error('AtomS3U moveTo timed out');
  }

  async function click(button = 'left', clickOptions = {}) {
    const normalizedButton = normalizeButton(button);
    await connect();

    const holdMs = Number.isFinite(Number(clickOptions.holdMs))
      ? clamp(Math.round(Number(clickOptions.holdMs)), 0, 5000)
      : options.clickHoldMs;
    const repeat = Number.isFinite(Number(clickOptions.repeat)) && Number(clickOptions.repeat) > 0
      ? Math.max(1, Math.round(Number(clickOptions.repeat)))
      : 1;
    const intervalMs = Number.isFinite(Number(clickOptions.intervalMs)) && Number(clickOptions.intervalMs) >= 0
      ? Math.round(Number(clickOptions.intervalMs))
      : options.clickIntervalMs;
    const preDelayMs = Number.isFinite(Number(clickOptions.preDelayMs)) && Number(clickOptions.preDelayMs) >= 0
      ? Math.round(Number(clickOptions.preDelayMs))
      : options.clickPreDelayMs;
    const postDelayMs = Number.isFinite(Number(clickOptions.postDelayMs)) && Number(clickOptions.postDelayMs) >= 0
      ? Math.round(Number(clickOptions.postDelayMs))
      : options.clickPostDelayMs;

    if (preDelayMs > 0) {
      await sleep(preDelayMs);
    }

    for (let index = 0; index < repeat; index += 1) {
      await sendCommand(`CLICK ${normalizedButton} ${holdMs}`, (line) => line === 'OK CLICK');
      if (index < repeat - 1) {
        await sleep(intervalMs);
      }
    }

    if (postDelayMs > 0) {
      await sleep(postDelayMs);
    }
  }

  async function mouseDown(button = 'left') {
    const normalizedButton = normalizeButton(button);
    await connect();
    await sendCommand(`DOWN ${normalizedButton}`, (line) => line === 'OK DOWN');
  }

  async function mouseUp(button = 'left') {
    const normalizedButton = normalizeButton(button);
    await connect();
    await sendCommand(`UP ${normalizedButton}`, (line) => line === 'OK UP');
  }

  async function moveAndClick(targetX, targetY, getCursorPosOrButton, buttonOrOptions = 'left', maybeOptions = {}) {
    if (typeof getCursorPosOrButton === 'function') {
      await moveTo(targetX, targetY, getCursorPosOrButton);
      await click(buttonOrOptions, maybeOptions);
      return;
    }

    await moveTo(targetX, targetY);
    if (typeof getCursorPosOrButton === 'object' && getCursorPosOrButton !== null) {
      await click('left', getCursorPosOrButton);
      return;
    }

    await click(getCursorPosOrButton || 'left', typeof buttonOrOptions === 'object' ? buttonOrOptions : maybeOptions);
  }

  function getPressedKeyArray() {
    return Array.from(pressedKeyCodes).slice(0, 6);
  }

  async function syncKeyboardState() {
    await connect();
    const keys = getPressedKeyArray();
    const paddedKeys = [...keys, 0, 0, 0, 0, 0, 0].slice(0, 6);
    await sendCommand(
      `KEY ${pressedModifierMask} ${paddedKeys.join(' ')}`,
      (line) => line === 'OK KEY'
    );
  }

  async function keyToggle(key, state) {
    const normalizedState = state === 'down' ? 'down' : 'up';
    const modifierMask = getModifierMask(key);
    const keyCode = getKeyCode(key);

    if (isModifierKey(key)) {
      if (normalizedState === 'down') {
        pressedModifierMask |= modifierMask;
      } else {
        pressedModifierMask &= ~modifierMask;
      }
      await syncKeyboardState();
      return;
    }

    if (!keyCode) {
      throw new Error(`Unsupported AtomS3U keyToggle key: ${key}`);
    }

    if (normalizedState === 'down') {
      pressedKeyCodes.add(keyCode);
    } else {
      pressedKeyCodes.delete(keyCode);
    }

    await syncKeyboardState();
  }

  async function keyTap(key, modifiersOrOptions = [], maybeOptions = {}) {
    const keyCode = getKeyCode(key);
    if (!keyCode) {
      throw new Error(`Unsupported AtomS3U keyTap key: ${key}`);
    }

    const keyTapArgs = normalizeKeyTapArgs(modifiersOrOptions, maybeOptions);
    const mask = keyTapArgs.modifiers.reduce((value, modifier) => {
      const modifierMask = getModifierMask(modifier);
      if (!modifierMask) {
        throw new Error(`Unsupported AtomS3U keyTap modifier: ${modifier}`);
      }
      return value | modifierMask;
    }, 0);
    const configuredHoldMs = Number.isFinite(Number(keyTapArgs.options.holdMs))
      ? Number(keyTapArgs.options.holdMs)
      : options.keyHoldMs;
    const holdMs = clamp(Math.round(Number(configuredHoldMs) || DEFAULT_OPTIONS.keyHoldMs), 0, 5000);
    await connect();
    await sendCommand(`KEYTAP ${mask} ${keyCode} ${holdMs}`, (line) => line === 'OK KEYTAP');
  }

  async function releaseKeys() {
    resetKeyState();
    await connect();
    await sendCommand('RELEASE_KEYS', (line) => line === 'OK RELEASE_KEYS');
  }

  async function pasteShortcut(platform = options.platform) {
    const modifier = normalizePlatform(platform) === 'darwin' ? 'command' : 'control';
    await keyTap('v', [modifier]);
    await keyToggle(modifier, 'up');
  }

  return {
    connect,
    disconnect,
    listDevices: () => listDevices(options),
    getHealth,
    moveTo,
    click,
    mouseDown,
    mouseUp,
    moveAndClick,
    keyTap,
    keyToggle,
    releaseKeys,
    pasteShortcut,
    _debug: {
      sendRelativeMove,
      buildRelativeStep: (dx, dy) => buildRelativeStep(dx, dy, options)
    }
  };
}

function createInputFromDetectedDevice(detection, options = {}) {
  if (!detection?.available || !detection?.portPath) {
    throw new Error(detection?.reason || 'No available AtomS3U HID device detected');
  }

  return createAtomS3UInput({
    ...options,
    portPath: detection.portPath,
    baudRate: detection.baudRate || options.baudRate || DEFAULT_OPTIONS.baudRate
  });
}

async function createInputFromAutoDetect(options = {}) {
  const detection = await autoDetectAtomS3U(options);
  return {
    detection,
    input: createInputFromDetectedDevice(detection, options)
  };
}

module.exports = {
  autoDetectAtomS3U,
  autoDetectInputDevice: autoDetectAtomS3U,
  createAtomS3UInput,
  createInputFromAutoDetect,
  createInputFromDetectedDevice,
  detectAtomS3UDevices,
  listDevices,
  probeAtomS3UDevice,
  probeInputDevice: probeAtomS3UDevice,
  _internal: {
    buildRelativeStep,
    normalizePoint
  }
};
